use std::fs::Metadata;
use std::time::{SystemTime, UNIX_EPOCH};

fn system_time_to_unix_seconds(time: SystemTime) -> i64 {
    match time.duration_since(UNIX_EPOCH) {
        Ok(duration) => duration.as_secs() as i64,
        Err(error) => -(error.duration().as_secs() as i64),
    }
}

