/// An entry a directory lists: its name, and its kind where the listing
/// says (no look-up).
impl Listed {
    pub(crate) fn name(&self) -> &OsStr {
        &self.name
    }

    pub(crate) fn kind(&self) -> Option<Kind> {
        self.kind
    }
}

